   1→/**
   2→ * render-html.ts — Prism HTML report renderer (deterministic, no LLM).
   3→ *
   4→ * Usage (from cwd web/):
   5→ *   node --import tsx server/prism/render-html.ts --dir <run-output-dir>
   6→ *
   7→ * Reads:   <dir>/narrative.json  (required — NarrativeReport shape)
   8→ *          <dir>/verdict.json    (optional — numeric metric strip)
   9→ * Outputs: <dir>/report.html
  10→ *
  11→ * Features:
  12→ * - Self-contained HTML (inline CSS + JS, opens by double-click)
  13→ * - Dark Unity-Timeline-inspired theme
  14→ * - Narrative-flow structure: overview → topConclusions → sections → prioritySummary
  15→ * - Flame-bar call-tree re-queried from real DB at render time (drillDownMarker)
  16→ * - Zero audit info (证据链/自我审查/技术论证) — narrative.json has none
  17→ */
  18→
  19→import * as fs from 'fs';
  20→import * as path from 'path';
  21→import { fileURLToPath } from 'node:url';
  22→import { openPrismDb } from './db.js';
  23→import { drillDownMarker } from './tools.js';
  24→import type { DrillDownNode } from './tools.js';
  25→import type { NarrativeReport, NarrativeItem, VisualAsset } from './narrative-types.js';
  26→
  27→// udiff 根目录：web/data/results/。与 tools.ts:3576 UNITY_UDIFF_ROOT 对齐。
  28→// LLM 默认 runId=udiff_1782983710451_be175ef1，按 runId 拼路径 web/data/results/<runId>/<role>/preprocess-result.json。
  29→const UNITY_UDIFF_ROOT = path.resolve(
  30→  path.dirname(fileURLToPath(import.meta.url)),
  31→  '../../data/results'
  32→);
  33→
  34→// ─────────────────────── WT-045: callTree 渲染剪枝阈值 ───────────────────────
  35→// 数据源无关的通用阈值（不是硬编码业务名），仿 drillDownMarker 的 maxDepth/minMsPerFrame/topPerLevel。
  36→// 适用于 unityAggNodeToDrillDown / perfettoNodeToDrillDown 数据转换层（renderTreeHTML 不改，只渲染）。
  37→// 红线条目（redlineFlag/foldChange/severityTag）例外：即使 perFrameMs 低也必保留，不剪枝。
  38→const MAX_TREE_DEPTH = 8;       // 递归深度超过 8 层不再展开 children
  39→const MIN_MS_PER_FRAME = 0.05;  // 子节点 perFrameMs < 0.05ms 且无红线标注的，不渲染
  40→const TOP_PER_LEVEL = 8;        // 每层只取 perFrameMs top 8 个子节点（红线标注的例外，必保留）
  41→
  42→// ─────────────────────── Verdict numeric metrics shape ───────────────────────
  43→
  44→interface Verdict {
  45→  runId?: string;
  46→  rating?: string;
  47→  frameBudgetMs?: number;
  48→  observedP50Ms?: number;
  49→  observedP95Ms?: number;
  50→  observedP99Ms?: number;
  51→  observedMaxMs?: number;
  52→  observedMaxFrameIndex?: number;
  53→  pctFramesOverBudget?: number;
  54→}
  55→
  56→// ─────────────────────── Tiny helpers ───────────────────────
  57→
  58→function htmlEsc(s: unknown): string {
  59→  if (s == null) return '';
  60→  return String(s)
  61→    .replace(/&/g, '&amp;')
  62→    .replace(/</g, '&lt;')
  63→    .replace(/>/g, '&gt;')
  64→    .replace(/"/g, '&quot;')
  65→    .replace(/'/g, '&#39;');
  66→}
  67→
  68→function num(v: unknown, digits = 1): string {
  69→  if (typeof v === 'number' && isFinite(v)) return v.toFixed(digits);
  70→  return '—';
  71→}
  72→
  73→// ─────────────────────── Minimal markdown renderer (WT-030) ───────────────────────
  74→// 支持 5 类 token：GFM 表格 / 代码围栏 / 粗体 / 行内代码 / 换行。
  75→// 不引入 markdown 库（marked/markdown-it 等都不引），手写最小解析器。
  76→// 复杂 markdown（标题 # / 列表 - / 链接 []() / 图片 ![]()）降级为纯文本，不报错。
  77→// 先 htmlEsc 再解析 token，避免 XSS（narrative.json 是 LLM 产的，内容不可信）。
  78→
  79→/**
  80→ * 把已经 htmlEsc 过的单元格文本做行内 token 解析（粗体 / 行内代码）。
  81→ * 不解析表格/代码围栏/换行（这些是块级 token，由 renderMarkdownLite 处理）。
  82→ */
  83→export function renderInlineMarkdown(s: string): string {
  84→  // 行内代码 `x` → <code>x</code>（先处理代码，避免代码内的 ** 被解析成粗体）
  85→  let out = '';
  86→  let i = 0;
  87→  while (i < s.length) {
  88→    const ch = s[i];
  89→    if (ch === '`') {
  90→      // 找下一个反引号
  91→      const end = s.indexOf('`', i + 1);
  92→      if (end === -1) {
  93→        out += ch;
  94→        i++;
  95→        continue;
  96→      }
  97→      const code = s.slice(i + 1, end);
  98→      out += `<code>${code}</code>`;
  99→      i = end + 1;
 100→      continue;
 101→    }
 102→    if (ch === '*' && s[i + 1] === '*') {
 103→      // 粗体 **x** → <strong>x</strong>
 104→      const end = s.indexOf('**', i + 2);
 105→      if (end === -1) {
 106→        out += ch;
 107→        i++;
 108→        continue;
 109→      }
 110→      const inner = s.slice(i + 2, end);
 111→      out += `<strong>${renderInlineMarkdown(inner)}</strong>`;
 112→      i = end + 2;
 113→      continue;
 114→    }
 115→    out += ch;
 116→    i++;
 117→  }
 118→  return out;
 119→}
 120→
 121→/** 判断一行是否是 GFM 表格的分隔行（|---|---| 形式） */
 122→function isTableSeparatorRow(line: string): boolean {
 123→  const trimmed = line.trim();
 124→  if (!trimmed.includes('|')) return false;
 125→  // 去掉首尾 | 后，每段应全是 -、:、空格
 126→  const inner = trimmed.replace(/^\|/, '').replace(/\|$/, '').trim();
 127→  if (inner === '') return false;
 128→  const cells = inner.split('|');
 129→  if (cells.length === 0) return false;
 130→  return cells.every(c => /^\s*:?-+:?\s*$/.test(c));
 131→}
 132→
 133→/** 判断一行是否是表格行（含 | 且不是分隔行） */
 134→function isTableRow(line: string): boolean {
 135→  const trimmed = line.trim();
 136→  if (!trimmed.includes('|')) return false;
 137→  if (isTableSeparatorRow(line)) return false;
 138→  // 至少有一个 | 把行分成 >=2 段
 139→  return trimmed.split('|').filter(s => s.trim() !== '' || true).length >= 2;
 140→}
 141→
 142→/** 解析表格行（去首尾 |，按 | 分列，trim 每格） */
 143→function parseTableRow(line: string): string[] {
 144→  let trimmed = line.trim();
 145→  // 去掉首尾的 |（如果有）
 146→  if (trimmed.startsWith('|')) trimmed = trimmed.slice(1);
 147→  if (trimmed.endsWith('|')) trimmed = trimmed.slice(0, -1);
 148→  return trimmed.split('|').map(c => c.trim());
 149→}
 150→
 151→/**
 152→ * 把一段 markdown 文本渲染成 HTML 片段（不含外层 <p>）。
 153→ *
 154→ * 流程：
 155→ *   1. 先 htmlEsc 整个文本（XSS 防护）
 156→ *   2. 按代码围栏 ``` 切段（代码优先，围栏内的 | 不解析为表格）
 157→ *   3. 在非代码段里按连续表格行切块（表格优先，表格外才做行内 token）
 158→ *   4. 行内 token（粗体 / 行内代码）最后处理
 159→ */
 160→export function renderMarkdownLite(md: string): string {
 161→  if (!md) return '';
 162→
 163→  // Step 1: htmlEsc 整个文本
 164→  const escaped = htmlEsc(md);
 165→
 166→  // Step 2: 按代码围栏切段
 167→  const fenceRe = /```[^\n]*\n?[\s\S]*?```/g;
 168→  const segments: { type: 'code' | 'text'; content: string }[] = [];
 169→  let lastIdx = 0;
 170→  let fenceMatch: RegExpExecArray | null;
 171→  while ((fenceMatch = fenceRe.exec(escaped)) !== null) {
 172→    if (fenceMatch.index > lastIdx) {
 173→      segments.push({ type: 'text', content: escaped.slice(lastIdx, fenceMatch.index) });
 174→    }
 175→    segments.push({ type: 'code', content: fenceMatch[0] });
 176→    lastIdx = fenceMatch.index + fenceMatch[0].length;
 177→  }
 178→  if (lastIdx < escaped.length) {
 179→    segments.push({ type: 'text', content: escaped.slice(lastIdx) });
 180→  }
 181→
 182→  const blocks: string[] = [];
 183→
 184→  for (const seg of segments) {
 185→    if (seg.type === 'code') {
 186→      // 代码围栏：```lang\ncode\n``` → <pre><code>code</code></pre>
 187→      // 去掉开头的 ```lang 和结尾的 ```
 188→      let content = seg.content;
 189→      // 去掉开头 ``` 和可选语言标识
 190→      content = content.replace(/^```[^\n]*\n?/, '');
 191→      content = content.replace(/```$/, '');
 192→      // content 已经 htmlEsc 过（整个 escaped 已 esc），直接放 <pre><code>
 193→      blocks.push(`<pre><code>${content}</code></pre>`);
 194→      continue;
 195→    }
 196→
 197→    // 文本段：按行扫描，识别表格块
 198→    const lines = seg.content.split('\n');
 199→    let i = 0;
 200→    while (i < lines.length) {
 201→      const line = lines[i];
 202→
 203→      // 检测表格块：连续的表格行 + 分隔行
 204→      if (isTableRow(line)) {
 205→        // 看下面是否紧跟分隔行 + 数据行
 206→        // 标准 GFM 表格：表头行 + 分隔行 + 数据行+
 207→        if (i + 1 < lines.length && isTableSeparatorRow(lines[i + 1])) {
 208→          // 完整表格：收集表头 + 分隔行 + 后续数据行
 209→          const headerCells = parseTableRow(line);
 210→          let j = i + 2;
 211→          const dataRows: string[][] = [];
 212→          while (j < lines.length && isTableRow(lines[j])) {
 213→            dataRows.push(parseTableRow(lines[j]));
 214→            j++;
 215→          }
 216→          // 渲染表格
 217→          const thead = `<thead><tr>${headerCells.map(c => `<th>${renderInlineMarkdown(c)}</th>`).join('')}</tr></thead>`;
 218→          const tbody = dataRows.length
 219→            ? `<tbody>${dataRows.map(row => `<tr>${row.map(c => `<td>${renderInlineMarkdown(c)}</td>`).join('')}</tr>`).join('')}</tbody>`
 220→            : '';
 221→          blocks.push(`<table>${thead}${tbody}</table>`);
 222→          i = j;
 223→          continue;
 224→        }
 225→        // 不是完整表格（无分隔行）→ 当普通文本行处理（降级）
 226→      }
 227→
 228→      // 普通文本行：行内 token + 换行
 229→      // 空行不渲染（避免连续 <br>）
 230→      if (line.trim() === '') {
 231→        i++;
 232→        continue;
 233→      }
 234→      blocks.push(renderInlineMarkdown(line) + '<br>');
 235→      i++;
 236→    }
 237→  }
 238→
 239→  // 拼接所有块，去掉末尾多余的 <br>
 240→  let result = blocks.join('\n');
 241→  result = result.replace(/(<br>)\s*$/,'');
 242→  return result;
 243→}
 244→
 245→/** Category color from marker name (Unity Timeline palette). */
 246→function categoryColor(markerName: string): { bg: string; border: string; text: string } {
 247→  const n = markerName.toLowerCase();
 248→  if (/gc\.|collect|alloc|garbage/.test(n))
 249→    return { bg: '#f443361a', border: '#f44336', text: '#ff7961' };
 250→  if (/wait|semaphore|idle|sync|present/.test(n))
 251→    return { bg: '#9e9e9e1a', border: '#757575', text: '#bdbdbd' };
 252→  if (/render|urp|gfx|draw|mesh|vr|blit|shadow|depth|pass|camera/.test(n))
 253→    return { bg: '#4caf501a', border: '#4caf50', text: '#81c784' };
 254→  if (/update|mgr|manager|cs:|lua|script|behaviour|mono/.test(n))
 255→    return { bg: '#2196f31a', border: '#2196f3', text: '#64b5f6' };
 256→  if (/job|worker|burst|thread|batch/.test(n))
 257→    return { bg: '#9c27b01a', border: '#9c27b0', text: '#ce93d8' };
 258→  if (/network|server|ntf|msg|socket|tserver/.test(n))
 259→    return { bg: '#0096881a', border: '#009688', text: '#4db6ac' };
 260→  return { bg: '#78909c1a', border: '#546e7a', text: '#90a4ae' };
 261→}
 262→
 263→const SEV_CN: Record<string, string> = {
 264→  critical: '严重', high: '高', medium: '中', low: '低', info: '信息',
 265→};
 266→const SEV_COLOR: Record<string, { dot: string; badge: string }> = {
 267→  critical: { dot: '#f44336', badge: '#f4433620' },
 268→  high:     { dot: '#ff9800', badge: '#ff980020' },
 269→  medium:   { dot: '#ffc107', badge: '#ffc10720' },
 270→  low:      { dot: '#4caf50', badge: '#4caf5020' },
 271→  info:     { dot: '#2196f3', badge: '#2196f320' },
 272→};
 273→const KIND_CN: Record<string, string> = {
 274→  '稳态大头': '稳态大头', '高频尖峰': '高频尖峰', '低频尖峰': '低频尖峰',
 275→};
 276→const RATING_MAP: Record<string, { emoji: string; label: string; color: string; bg: string }> = {
 277→  excellent: { emoji: '🟢', label: '优秀',  color: '#4caf50', bg: '#4caf5020' },
 278→  pass:      { emoji: '🟢', label: '及格',  color: '#8bc34a', bg: '#8bc34a20' },
 279→  weak:      { emoji: '🟡', label: '偏弱',  color: '#ffc107', bg: '#ffc10720' },
 280→  fail:      { emoji: '🔴', label: '不合格', color: '#f44336', bg: '#f4433620' },
 281→};
 282→
 283→function sevStyle(sev: string): { dot: string; badge: string } {
 284→  return SEV_COLOR[sev] ?? { dot: '#9e9e9e', badge: '#9e9e9e20' };
 285→}
 286→
 287→/** Theme-group accent colors — cycle by section index, not by heading name. */
 288→const SECTION_GROUP_COLORS = [
 289→  { border: '#2196f3', bg: '#2196f318' },
 290→  { border: '#ff9800', bg: '#ff980018' },
 291→  { border: '#9c27b0', bg: '#9c27b018' },
 292→  { border: '#78909c', bg: '#78909c18' },
 293→  { border: '#4caf50', bg: '#4caf5018' },
 294→  { border: '#009688', bg: '#00968818' },
 295→];
 296→
 297→function sectionGroupColor(index: number): { border: string; bg: string } {
 298→  return SECTION_GROUP_COLORS[index % SECTION_GROUP_COLORS.length];
 299→}
 300→
 301→// ─────────────────────── Call-tree rendering ───────────────────────
 302→
 303→function renderTreeHTML(node: DrillDownNode, rootMs: number, depth: number): string {
 304→  const totalMs = node.totalMsPerFrame;
 305→  const widthPct = rootMs > 0 ? Math.max(1, (totalMs / rootMs) * 100) : 100;
 306→  const col = categoryColor(node.name);
 307→  const indent = depth * 20;
 308→
 309→  const displayMs =
 310→    node.selfMsPerFrame > 0 && node.selfMsPerFrame < totalMs
 311→      ? `${totalMs.toFixed(2)}ms (self ${node.selfMsPerFrame.toFixed(2)}ms)`
 312→      : `${totalMs.toFixed(2)}ms`;
 313→  const pctStr = (node.pctOfRoot * 100).toFixed(1);
 314→
 315→  // WT-033: 节点红线/涨幅/严重度标注（从 findings 注入，render 只呈现不判定）
 316→  let annotationHTML = '';
 317→  if (node.redlineFlag) {
 318→    annotationHTML += `<span class="tree-redline" title="${htmlEsc(node.redlineFlag)}">🔴 ${htmlEsc(node.redlineFlag)}</span>`;
 319→  }
 320→  if (node.foldChange) {
 321→    annotationHTML += `<span class="tree-fold" title="涨幅 ${htmlEsc(node.foldChange)}">📈 ${htmlEsc(node.foldChange)}</span>`;
 322→  }
 323→  // severityTag 通过 data-sev 属性 + CSS 左边框色体现（不额外加文字标注，避免冗余）
 324→  const sevAttr = node.severityTag ? `data-sev="${htmlEsc(node.severityTag)}"` : '';
 325→
 326→  let html = `
 327→  <div class="tree-row" style="--tree-indent:${indent}px;--tree-width:${widthPct.toFixed(1)}%;--tree-bg:${col.bg};--tree-border:${col.border};">
 328→    <div class="tree-bar" ${sevAttr}>
 329→      <span class="tree-fill" aria-hidden="true"></span>
 330→      <span class="tree-label" style="color:${col.text}" title="${htmlEsc(node.name)}">${htmlEsc(node.name)}</span>
 331→      <span class="tree-ms">${htmlEsc(displayMs)}</span>
 332→      <span class="tree-pct">${pctStr}%</span>
 333→      ${annotationHTML}
 334→    </div>
 335→  </div>`;
 336→
 337→  for (const child of node.children ?? []) {
 338→    html += renderTreeHTML(child, rootMs, depth + 1);
 339→  }
 340→  return html;
 341→}
 342→
 343→const TREE_LEGEND = `
 344→  <span class="legend-item" style="color:#81c784">■ 渲染</span>
 345→  <span class="legend-item" style="color:#64b5f6">■ 脚本</span>
 346→  <span class="legend-item" style="color:#ff7961">■ GC/内存</span>
 347→  <span class="legend-item" style="color:#bdbdbd">■ 等待</span>
 348→  <span class="legend-item" style="color:#ce93d8">■ Job</span>
 349→  <span class="legend-item" style="color:#4db6ac">■ 网络</span>`;
 350→
 351→// ─────────────────────── Visual asset rendering (WT-036) ───────────────────────
 352→// 视觉资产从顶层字段移到 NarrativeItem.visualAsset，render 按 type 渲染。
 353→// 通用类型：table（表格）/ ascii（ASCII 图）/ matrix（矩阵，按 levelColumn 上色）。
 354→// 不硬编码 perfetto 特有字段名（metaInfo/threadOverview/throttlingMatrix/redlineMatrix）。
 355→
 356→/** 矩阵判定档颜色（confirmed/likely/suspected 三档，通用） */
 357→function matrixLevelClass(level: string): string {
 358→  const l = String(level).toLowerCase();
 359→  if (l === 'confirmed') return 'tm-confirmed';
 360→  if (l === 'likely') return 'tm-likely';
 361→  return 'tm-suspected';
 362→}
 363→
 364→/** 渲染视觉资产（WT-036：item.visualAsset，按 type 渲染） */
 365→function renderVisualAsset(asset: VisualAsset): string {
 366→  if (asset.type === 'ascii') {
 367→    const content = asset.ascii?.content ?? '';
 368→    if (!content) return '';
 369→    return `<div class="ascii-art-block">
 370→      <div class="ascii-art-title">${htmlEsc(asset.title)}</div>
 371→      <pre class="ascii-art-content">${htmlEsc(content)}</pre>
 372→      ${asset.ascii?.caption ? `<div class="ascii-art-caption">${htmlEsc(asset.ascii.caption)}</div>` : ''}
 373→    </div>`;
 374→  }
 375→
 376→  // table 或 matrix：都渲染成 <table>，matrix 按 levelColumn 上色
 377→  const table = asset.table;
 378→  if (!table || !Array.isArray(table.headers) || table.headers.length === 0) return '';
 379→
 380→  const levelColIdx = asset.type === 'matrix' && asset.levelColumn
 381→    ? table.headers.findIndex(h => h === asset.levelColumn)
 382→    : -1;
 383→
 384→  const headerHTML = `<thead><tr>${table.headers.map(h => `<th>${htmlEsc(h)}</th>`).join('')}</tr></thead>`;
 385→  const bodyHTML = `<tbody>${table.rows.map(row => {
 386→    const cells = Array.isArray(row) ? row : [];
 387→    // matrix 行按 levelColumn 的值上色
 388→    const levelVal = levelColIdx >= 0 ? String(cells[levelColIdx] ?? '') : '';
 389→    const rowClass = asset.type === 'matrix' && levelVal ? matrixLevelClass(levelVal) : '';
 390→    const cellsHTML = table.headers.map((_, i) => `<td>${htmlEsc(String(cells[i] ?? '—'))}</td>`).join('');
 391→    return `<tr${rowClass ? ` class="${rowClass}"` : ''}>${cellsHTML}</tr>`;
 392→  }).join('')}</tbody>`;
 393→
 394→  return `<div class="visual-asset-block">
 395→    <div class="visual-asset-title">${htmlEsc(asset.title)}</div>
 396→    <table class="asset-table${asset.type === 'matrix' ? ' matrix-table' : ''}">${headerHTML}${bodyHTML}</table>
 397→  </div>`;
 398→}
 399→
 400→// ─────────────────────── Narrative item card ───────────────────────
 401→
 402→function renderItemCard(item: NarrativeItem, tree: DrillDownNode | null | undefined): string {
 403→  const sc = sevStyle(item.severity);
 404→
 405→  // Flame-bar tree (or fallback note)
 406→  let treeSection = '';
 407→  if (tree) {
 408→    const rootMs = tree.totalMsPerFrame;
 409→    treeSection = `
 410→    <div class="tree-section">
 411→      <div class="tree-header">
 412→        <span class="tree-title">调用树（per-frame avg）</span>
 413→        <span class="tree-legend">${TREE_LEGEND}</span>
 414→      </div>
 415→      <div class="tree-container">
 416→        ${renderTreeHTML(tree, rootMs, 0)}
 417→      </div>
 418→    </div>`;
 419→  } else if (item.callTree?.note) {
 420→    treeSection = `
 421→    <div class="tree-section fallback">
 422→      <div class="tree-header"><span class="tree-title">调用树备注</span></div>
 423→      <div class="tree-note">${htmlEsc(item.callTree.note)}</div>
 424→    </div>`;
 425→  }
 426→
 427→  // WT-036: 视觉资产渲染在 narrative 下方、callTree 上方（item.visualAsset，不是顶层字段）
 428→  const visualAssetHTML = item.visualAsset ? renderVisualAsset(item.visualAsset) : '';
 429→
 430→  // sourceInsight callout（保持 htmlEsc + <br>——它是代码片段，不需要表格）
 431→  const insightSection = item.sourceInsight
 432→    ? `<div class="source-insight"><span class="insight-label">源码归因</span>${htmlEsc(item.sourceInsight).replace(/\n/g, '<br>')}</div>`
 433→    : '';
 434→
 435→  // Recommendations numbered list
 436→  const recs = Array.isArray(item.recommendations) ? item.recommendations : [];
 437→  const recsHTML = recs.length
 438→    ? `<div class="rec-section">
 439→        <div class="rec-label">优化建议</div>
 440→        <ol class="rec-list">${recs.map(r => `<li>${htmlEsc(r)}</li>`).join('')}</ol>
 441→      </div>`
 442→    : '';
 443→
 444→  return `
 445→  <div class="item-card">
 446→    <div class="item-header">
 447→      <span class="sev-dot" style="background:${sc.dot}" title="${SEV_CN[item.severity] ?? item.severity}"></span>
 448→      <span class="item-title">${htmlEsc(item.title)}</span>
 449→      <span class="chip sev-chip" style="color:${sc.dot};background:${sc.badge}">${SEV_CN[item.severity] ?? item.severity}</span>
 450→    </div>
 451→    <div class="item-body">
 452→      <p class="narrative-text">${renderMarkdownLite(item.narrative)}</p>
 453→      ${visualAssetHTML}
 454→      ${treeSection}
 455→      ${insightSection}
 456→      ${recsHTML}
 457→    </div>
 458→  </div>`;
 459→}
 460→
 461→// ─────────────────────── Main HTML builder ───────────────────────
 462→
 463→interface RenderOptions {
 464→  narrative: NarrativeReport;
 465→  verdict: Verdict | null;
 466→  treesByItemKey: Map<string, DrillDownNode | null>;
 467→}
 468→
 469→function renderHTML(opts: RenderOptions): string {
 470→  const { narrative, verdict, treesByItemKey } = opts;
 471→  // WT-046 v5: treesByKey 只含 section items（key=<heading>::<i>）——topConclusions 是纯索引表，不挂 HTML 树/ASCII/note
 472→  const treesByKey = treesByItemKey;
 473→
 474→  const ratingInfo = RATING_MAP[narrative.rating] ?? { emoji: '—', label: narrative.rating ?? '—', color: '#9e9e9e', bg: '#9e9e9e20' };
 475→
 476→  // ── Metrics strip ──
 477→  const budget = verdict?.frameBudgetMs ?? null;
 478→  const fps = budget ? Math.round(1000 / budget) : null;
 479→  const metrics = [
 480→    { label: '帧预算',  value: budget ? `${num(budget)}ms / ${fps}fps` : '—' },
 481→    { label: 'P50',    value: verdict?.observedP50Ms != null ? `${num(verdict.observedP50Ms)}ms` : '—' },
 482→    { label: 'P95',    value: verdict?.observedP95Ms != null ? `${num(verdict.observedP95Ms)}ms` : '—' },
 483→    { label: 'P99',    value: verdict?.observedP99Ms != null ? `${num(verdict.observedP99Ms)}ms` : '—' },
 484→    { label: '最差帧', value: verdict?.observedMaxMs != null
 485→        ? (verdict.observedMaxFrameIndex != null
 486→          ? `${num(verdict.observedMaxMs)}ms (#${verdict.observedMaxFrameIndex})`
 487→          : `${num(verdict.observedMaxMs)}ms`)
 488→        : '—' },
 489→    { label: '超预算%', value: verdict?.pctFramesOverBudget != null ? `${num(verdict.pctFramesOverBudget)}%` : '—' },
 490→  ];
 491→  const metricsHTML = metrics.map(m => `
 492→  <div class="metric-box">
 493→    <div class="metric-label">${htmlEsc(m.label)}</div>
 494→    <div class="metric-value">${htmlEsc(m.value)}</div>
 495→  </div>`).join('');
 496→
 497→  // ── § 核心结论 table ──
 498→  // WT-046 v5: topConclusions 是纯索引表（problem/kind/contribution/severity 4 列），不挂 extraHTML。
 499→  // 叙事展开（ASCII 图 + 人话 + 详见 §X）是 §0 的职责——§0 讲全部 N 条，和 topConclusions 一一对应。
 500→  const conclusionsHTML = narrative.topConclusions.map(row => {
 501→    const sc = sevStyle(row.severity);
 502→    return `<tr>
 503→      <td class="tc-rank">${row.rank}</td>
 504→      <td class="tc-problem">${htmlEsc(row.problem)}</td>
 505→      <td class="tc-kind">${htmlEsc(KIND_CN[row.kind] ?? row.kind)}</td>
 506→      <td class="tc-contribution">${htmlEsc(row.contribution)}</td>
 507→      <td class="tc-severity"><span class="chip sev-chip" style="color:${sc.dot};background:${sc.badge}">${SEV_CN[row.severity] ?? row.severity}</span></td>
 508→    </tr>`;
 509→  }).join('');
 510→
 511→  // ── ruledOut strip ──
 512→  const ruledOutHTML = (narrative.ruledOut ?? []).length
 513→    ? `<div class="ruled-out-strip">
 514→        <span class="ruled-out-label">已排除</span>
 515→        ${narrative.ruledOut!.map(r => `<span class="ruled-out-item" title="${htmlEsc(r.why)}">${htmlEsc(r.name)}: <em>${htmlEsc(r.why)}</em></span>`).join('')}
 516→      </div>`
 517→    : '';
 518→
 519→  // ── 视觉资产（WT-036：从顶层字段移到 section item.visualAsset，不再独立渲染） ──
 520→  // 视觉资产现在挂在 NarrativeItem.visualAsset 里，由 renderItemCard 内部渲染。
 521→  // 顶层不再有 metaInfo/threadOverview/throttlingMatrix/redlineMatrix/asciiArt 字段（perfetto 特有字段已删）。
 522→
 523→  // ── TOC anchors ──
 524→  const tocItems = [
 525→    { label: '核心结论', id: 'sec-core-conclusions' },
 526→    ...narrative.sections.map((sec, i) => ({ label: sec.heading, id: `sec-section-${i}` })),
 527→    { label: '优化优先级', id: 'sec-priority' },
 528→  ];
 529→  const tocHTML = `
 530→<div class="toc-block">
 531→  <div class="toc-title">目录</div>
 532→  <ul class="toc-list">
 533→    ${tocItems.map(item => `<li><a href="#${item.id}">${htmlEsc(item.label)}</a></li>`).join('')}
 534→  </ul>
 535→</div>`;
 536→
 537→  // ── § sections ──
 538→  // WT-036: 视觉资产在 item.visualAsset 里（由 renderItemCard 渲染），section 级不再关联视觉资产
 539→  const sectionsHTML = narrative.sections.map((sec, secIdx) => {
 540→    const gc = sectionGroupColor(secIdx);
 541→    const introHTML = sec.intro
 542→      ? `<p class="section-intro">${renderMarkdownLite(sec.intro)}</p>`
 543→      : '';
 544→
 545→    // WT-036: 视觉资产在 item.visualAsset 里，由 renderItemCard 渲染，section 级不再关联视觉资产
 546→    const itemsHTML = sec.items.map((item, i) => {
 547→      const key = `${sec.heading}::${i}`;
 548→      const tree = treesByItemKey.get(key);
 549→      return renderItemCard(item, tree);
 550→    }).join('');
 551→    return `
 552→  <div class="narrative-section">
 553→    <div class="section-heading" id="sec-section-${secIdx}" style="border-left:4px solid ${gc.border};background:${gc.bg}">
 554→      ${htmlEsc(sec.heading)}
 555→    </div>
 556→    ${introHTML}
 557→    <div class="items-list">${itemsHTML}</div>
 558→  </div>`;
 559→  }).join('');
 560→
 561→  // ── § 优化优先级 ──
 562→  const priorityHTML = narrative.prioritySummary.map(row => {
 563→    const isP0 = row.priority === 'P0';
 564→    return `<tr class="${isP0 ? 'priority-p0' : ''}">
 565→      <td class="pri-priority">${htmlEsc(row.priority)}</td>
 566→      <td class="pri-action">${htmlEsc(row.action)}</td>
 567→      <td class="pri-benefit">${htmlEsc(row.benefit)}</td>
 568→    </tr>`;
 569→  }).join('');
 570→
 571→  return `<!DOCTYPE html>
