1232→// ─────────────────────── Re-query call trees ───────────────────────
1233→
1234→/**
1235→ * 判断 narrative 是否来自 perfetto 源。
1236→ * perfetto runId 形如 "bk26b-perfetto-triad/2026-07-15_10-36-27"（含 perfetto）。
1237→ */
1238→function isPerfettoSource(narrative: NarrativeReport): boolean {
1239→  return /perfetto/i.test(narrative.runId);
1240→}
1241→
1242→/**
1243→ * WT-044: 判断 narrative 是否来自 unity 多态源。
1244→ * unity 多态 runId 形如 "udiff_1782983710451_be175ef1"（含 udiff_）。
1245→ * 多态数据在 dir 的祖先目录下的 base/ + cur/ 子目录里（preprocess-result.json）。
1246→ */
1247→function isUnityMultiStateSource(narrative: NarrativeReport): boolean {
1248→  return /udiff_/i.test(narrative.runId);
1249→}
1250→
1251→/**
1252→ * WT-044: unity 多态 callTree 节点（来自 preprocess-result.json 的 aggregatedCallTrees）。
1253→ * 字段：name/depth/msTotal/msPerFrameTotal/msSelf/msPerFrameSelf/presentOnFrameCount/
1254→ *      presentRate/threadPct/count/gcAllocCount/children。
1255→ */
1256→interface UnityAggNode {
1257→  name: string;
1258→  depth?: number;
1259→  msTotal?: number;
1260→  msPerFrameTotal?: number;
1261→  msSelf?: number;
1262→  msPerFrameSelf?: number;
1263→  presentOnFrameCount?: number;
1264→  presentRate?: number;
1265→  threadPct?: number;
1266→  count?: number;
1267→  gcAllocCount?: number;
1268→  children?: UnityAggNode[];
1269→}
1270→
1271→/**
1272→ * WT-044: 把 unity 多态节点转成 DrillDownNode 兼容结构（renderTreeHTML 只读这些字段）。
1273→ * 多态报告用 cur 态作主树（和 perfetto 一致），base 态数据通过 foldChange/delta 标注呈现。
1274→ *
1275→ * WT-045: 加三重剪枝（maxDepth≤8 + minMsPerFrame≥0.05 + topPerLevel≤8），仿 drillDownMarker。
1276→ * 红线条目（redlineFlag/foldChange/severityTag）例外必保留，即使 perFrameMs 低也不剪枝。
1277→ * 剪枝在数据转换层做，renderTreeHTML 不改（它只是纯渲染）。
1278→ *
1279→ * @param annotations 从 findings.json 读的 callTreeAnnotations map（按 nodeName 查）。
1280→ * @param depth 当前递归深度，根节点传 0。depth >= MAX_TREE_DEPTH 不再展开 children。
1281→ */
1282→function unityAggNodeToDrillDown(
1283→  node: UnityAggNode,
1284→  thread: string,
1285→  rootMsPerFrame: number,
1286→  annotations?: Map<string, CallTreeAnnotation>,
1287→  depth: number = 0,
1288→): DrillDownNode {
1289→  const totalMsPerFrame = node.msPerFrameTotal ?? 0;
1290→  const selfMsPerFrame = node.msPerFrameSelf ?? 0;
1291→  const pctOfRoot = rootMsPerFrame > 0 ? totalMsPerFrame / rootMsPerFrame : 0;
1292→  const ann = annotations?.get(node.name);
1293→
1294→  // WT-045: 三重剪枝 — depth 超过上限不再展开 children
1295→  let children: DrillDownNode[] = [];
1296→  if (depth < MAX_TREE_DEPTH && node.children && node.children.length > 0) {
1297→    // 1. 过滤：perFrameMs < MIN_MS_PER_FRAME 且无红线标注的，剪掉
1298→    // 2. 排序：按 msPerFrameTotal 降序（top contributors 优先）
1299→    // 3. 取 top N：slice(0, TOP_PER_LEVEL)
1300→    // 红线条目（ann 命中的）必保留，即使 perFrameMs 低
1301→    const pruned = node.children
1302→      .filter(c => {
1303→        const cMs = c.msPerFrameTotal ?? 0;
1304→        const cAnn = annotations?.get(c.name);
1305→        const hasAnnotation = !!(cAnn?.redlineFlag || cAnn?.foldChange || cAnn?.severityTag);
1306→        return cMs >= MIN_MS_PER_FRAME || hasAnnotation;
1307→      })
1308→      .sort((a, b) => (b.msPerFrameTotal ?? 0) - (a.msPerFrameTotal ?? 0));
1309→
1310→    // 红线条目必保留（即使排在 TOP_PER_LEVEL 之外），非红线取 top N
1311→    const kept: UnityAggNode[] = [];
1312→    let nonRedlineAdded = 0;
1313→    for (const c of pruned) {
1314→      const cAnn = annotations?.get(c.name);
1315→      const hasAnnotation = !!(cAnn?.redlineFlag || cAnn?.foldChange || cAnn?.severityTag);
1316→      if (hasAnnotation) {
1317→        kept.push(c);  // 红线条目必保留
1318→      } else if (nonRedlineAdded < TOP_PER_LEVEL) {
1319→        kept.push(c);
1320→        nonRedlineAdded++;
1321→      }
1322→    }
1323→    children = kept.map(c => unityAggNodeToDrillDown(c, thread, rootMsPerFrame, annotations, depth + 1));
1324→  }
1325→
1326→  return {
1327→    name: node.name,
1328→    thread,
1329→    totalMsPerFrame,
1330→    selfMsPerFrame,
1331→    pctOfRoot,
1332→    presentFrames: node.presentOnFrameCount ?? node.count ?? 0,
1333→    children,
1334→    redlineFlag: ann?.redlineFlag ?? undefined,
1335→    foldChange: ann?.foldChange ?? undefined,
1336→    severityTag: ann?.severityTag ?? undefined,
1337→  };
1338→}
1339→
1340→/**
1341→ * WT-044: 在 unity aggregatedCallTree 里按节点名搜索子树。
1342→ * 先精确匹配；失败则按名字核心部分子串回退（narrative LLM 可能用简写名）。
1343→ */
1344→function findUnityAggSubtree(root: UnityAggNode, targetName: string): UnityAggNode | null {
1345→  // 1. 精确匹配
1346→  const exact = findUnityAggSubtreeExact(root, targetName);
1347→  if (exact) return exact;
1348→  // 2. 子串回退：取 targetName 的核心部分（去前缀）
1349→  const core = extractNameCore(targetName);
1350→  if (!core || core.length < 4) return null;
1351→  const candidates: UnityAggNode[] = [];
1352→  collectUnityAggContainsMatch(root, core, candidates);
1353→  if (candidates.length === 1) return candidates[0];
1354→  return null;
1355→}
1356→
1357→function findUnityAggSubtreeExact(node: UnityAggNode, targetName: string): UnityAggNode | null {
1358→  if (node.name === targetName) return node;
1359→  for (const child of node.children ?? []) {
1360→    const found = findUnityAggSubtreeExact(child, targetName);
1361→    if (found) return found;
1362→  }
1363→  return null;
1364→}
1365→
1366→function collectUnityAggContainsMatch(node: UnityAggNode, core: string, out: UnityAggNode[]): void {
1367→  if (node.name.includes(core)) out.push(node);
1368→  for (const child of node.children ?? []) collectUnityAggContainsMatch(child, core, out);
1369→}
1370→
1371→/**
1372→ * WT-044: unity 多态源的 callTree 重查：读 preprocess-result.json 的 aggregatedCallTrees，
1373→ * 按 rootMarker 名在树里搜索子树，转成 DrillDownNode。
1374→ * 不走 sqlite / drillDownMarker（VG 数据没灌库，走 JSON 路线）。
1375→ *
1376→ * @param dir  run 输出目录（含 narrative.json），形如 .../udiff_xxx/<timestamp>
1377→ *             udiff 数据在 dir 的父目录下的 cur/preprocess-result.json
1378→ */
1379→function requeryUnityMultiStateTrees(
1380→  narrative: NarrativeReport,
1381→  refs: { key: string; rootMarker: string }[],
1382→  dir: string,
1383→): Map<string, DrillDownNode | null> {
1384→  const map = new Map<string, DrillDownNode | null>();
1385→  if (refs.length === 0) return map;
1386→
1387→  // udiff 数据目录：用 narrative.runId（=udiff_xxx）从 UNITY_UDIFF_ROOT 拼。
1388→  // preprocess-result.json 在 <UNITY_UDIFF_ROOT>/<runId>/cur/ 下（多态报告用 cur 态作主树）。
1389→  // 与 tools.ts:3576 UNITY_UDIFF_ROOT 对齐。
1390→  //
1391→  // WT-046: narrative LLM 可能把 runId 写成 "udiff_xxx/<timestamp>"（含输出子目录），
1392→  // 但数据在 web/data/results/udiff_xxx/ 下（不含时间戳）。提取 udiff_xxx 部分拼路径。
1393→  const rawRunId = narrative.runId ?? '';
1394→  const udiffRunId = rawRunId.includes('/')
1395→    ? rawRunId.split('/')[0]  // "udiff_xxx/<timestamp>" → "udiff_xxx"
1396→    : rawRunId;
1397→  const udiffRoot = path.join(UNITY_UDIFF_ROOT, udiffRunId);
1398→  const resultPath = path.join(udiffRoot, 'cur', 'preprocess-result.json');
1399→
1400→  if (!fs.existsSync(resultPath)) {
1401→    console.warn(`[render-html] unity multi-state result not found: ${resultPath} — all callTrees fallback`);
1402→    for (const ref of refs) map.set(ref.key, null);
1403→    return map;
1404→  }
1405→
1406→  let result: { aggregatedCallTrees?: { threadName?: string; roots?: UnityAggNode[] }[] };
1407→  try {
1408→    result = JSON.parse(fs.readFileSync(resultPath, 'utf-8'));
1409→  } catch (e) {
1410→    console.warn(`[render-html] unity multi-state result parse failed: ${(e as Error).message} — all callTrees fallback`);
1411→    for (const ref of refs) map.set(ref.key, null);
1412→    return map;
1413→  }
1414→
1415→  const callTrees = Array.isArray(result.aggregatedCallTrees) ? result.aggregatedCallTrees : [];
1416→  if (callTrees.length === 0) {
1417→    console.warn('[render-html] unity aggregatedCallTrees empty — all callTrees fallback');
1418→    for (const ref of refs) map.set(ref.key, null);
1419→    return map;
1420→  }
1421→
1422→  // 优先选主线程树（threadName 含 "Main Thread"），否则取第一个
1423→  const mainTree = callTrees.find(t => /Main Thread/i.test(String(t.threadName ?? ''))) ?? callTrees[0];
1424→  const thread = mainTree.threadName ?? '1:Main Thread';
1425→  const roots = mainTree.roots ?? [];
1426→  if (roots.length === 0) {
1427→    console.warn('[render-html] unity main tree roots empty — all callTrees fallback');
1428→    for (const ref of refs) map.set(ref.key, null);
1429→    return map;
1430→  }
1431→  const primaryRoot = roots[0];
1432→
1433→  // WT-033: 从 findings.json 读 callTreeAnnotations（explore LLM 产的节点标注）
1434→  const annotations = loadCallTreeAnnotations(dir);
1435→  if (annotations.size > 0) {
1436→    console.log(`[render-html] loaded ${annotations.size} callTree annotations from findings.json`);
1437→  }
1438→
1439→  for (const ref of refs) {
1440→    // 先在主 root 子树里找；若 ref.rootMarker 就是主 root 名，直接用主 root
1441→    let subtree: UnityAggNode | null = null;
1442→    if (primaryRoot.name === ref.rootMarker) {
1443→      subtree = primaryRoot;
1444→    } else {
1445→      subtree = findUnityAggSubtree(primaryRoot, ref.rootMarker);
1446→      // 若主 root 子树里找不到，遍历其它 roots
1447→      if (!subtree) {
1448→        for (const r of roots) {
1449→          if (r.name === ref.rootMarker) { subtree = r; break; }
1450→          const found = findUnityAggSubtree(r, ref.rootMarker);
1451→          if (found) { subtree = found; break; }
1452→        }
1453→      }
1454→    }
1455→    if (subtree) {
1456→      const rootMsPerFrame = subtree.msPerFrameTotal ?? 0;
1457→      const tree = unityAggNodeToDrillDown(subtree, thread, rootMsPerFrame, annotations);
1458→      map.set(ref.key, tree);
1459→      console.log(`[render-html] unity multi-state tree OK: "${ref.rootMarker}" → ${tree.totalMsPerFrame.toFixed(2)}ms/frame`);
1460→    } else {
1461→      console.warn(`[render-html] unity multi-state tree NOT FOUND: "${ref.rootMarker}" — fallback to note`);
1462→      map.set(ref.key, null);
1463→    }
1464→  }
1465→  return map;
1466→}
1467→
1468→/**
1469→ * perfetto callTree 节点（来自 perfetto-profile-summary.json）的松散结构。
1470→ * 字段：name/totalMs/totalPct/count/layer/children。
1471→ */
1472→interface PerfettoNode {
1473→  name: string;
1474→  totalMs?: number;
1475→  totalPct?: number;
1476→  count?: number;
1477→  layer?: string;
1478→  children?: PerfettoNode[];
1479→}
1480→
1481→// ─── WT-033: callTree 节点标注（从 findings.json 的 evidence.resultDigest.callTreeAnnotations 注入） ───
1482→
1483→/** explore LLM 在 finding 的 evidence.resultDigest.callTreeAnnotations 里产的结构化标注 */
1484→interface CallTreeAnnotation {
1485→  nodeName: string;
1486→  redlineFlag?: string | null;
1487→  foldChange?: string | null;
1488→  severityTag?: 'critical' | 'high' | 'medium' | 'low' | 'healthy' | null;
1489→}
1490→
1491→/**
1492→ * 从 findings.json 读所有 finding 的 evidence.resultDigest.callTreeAnnotations，建 nodeName → annotation map。
1493→ * render 只读取并呈现，不写判定逻辑（判定在 explore LLM）。
1494→ * findings.json 不存在或字段缺失时返回空 map（容错，不报错）。
1495→ */
1496→function loadCallTreeAnnotations(dir: string): Map<string, CallTreeAnnotation> {
1497→  const map = new Map<string, CallTreeAnnotation>();
1498→  const findingsPath = path.join(dir, 'findings.json');
1499→  if (!fs.existsSync(findingsPath)) return map;
1500→  try {
1501→    const findings = JSON.parse(fs.readFileSync(findingsPath, 'utf-8'));
1502→    if (!Array.isArray(findings)) return map;
1503→    for (const f of findings) {
1504→      // evidence 可能是数组或对象，resultDigest 在 evidence 里
1505→      const evidence = f?.evidence;
1506→      if (!evidence) continue;
1507→      const evidenceList = Array.isArray(evidence) ? evidence : [evidence];
1508→      for (const ev of evidenceList) {
1509→        const annotations = ev?.resultDigest?.callTreeAnnotations;
1510→        if (!Array.isArray(annotations)) continue;
1511→        for (const ann of annotations) {
1512→          if (ann && typeof ann.nodeName === 'string') {
1513→            // 后写的覆盖先写的（同一节点名多次出现时取最新）
1514→            map.set(ann.nodeName, ann as CallTreeAnnotation);
1515→          }
1516→        }
1517→      }
1518→    }
1519→  } catch {
1520→    // findings.json 解析失败 = 容错，返回空 map（render 不报错，只是没标注）
1521→  }
1522→  return map;
1523→}
1524→
1525→/**
1526→ * 在 perfetto callTree 里按节点名搜索子树。
1527→ * 先精确匹配 rootMarker；失败则按名字核心部分（去前缀/去 Gfx./URP. 等命名空间差异）子串回退。
1528→ *
1529→ * 名字归一化（呈现层职责，非判定）：narrative LLM 可能用 atrace slice 名
1530→ * （如 Gfx.WaitForPresentOnGfxThread）而 callTree 用 Unity marker 名（如 URP.WaitForPresent），
1531→ * 两者指同一等待点。render 层做名字归一化让树能渲染，不做任何性能判定。
1532→ */
1533→function findPerfettoSubtree(root: PerfettoNode, targetName: string): PerfettoNode | null {
1534→  // 1. 精确匹配
1535→  const exact = findPerfettoSubtreeExact(root, targetName);
1536→  if (exact) return exact;
1537→
1538→  // 2. 子串回退：取 targetName 的核心部分（去前缀，取最后一个 CamelCase 词组）
1539→  //    如 Gfx.WaitForPresentOnGfxThread → WaitForPresent；Core.Update → Update
1540→  //    在树里找 name 包含核心词的节点，唯一匹配则用，多匹配则不用（避免误匹配）
1541→  const core = extractNameCore(targetName);
1542→  if (!core || core.length < 4) return null;  // 太短的核心词易误匹配，不回退
1543→  const candidates: PerfettoNode[] = [];
1544→  collectContainsMatch(root, core, candidates);
1545→  if (candidates.length === 1) return candidates[0];
1546→  return null;
1547→}
1548→
1549→function findPerfettoSubtreeExact(node: PerfettoNode, targetName: string): PerfettoNode | null {
1550→  if (node.name === targetName) return node;
1551→  for (const child of node.children ?? []) {
1552→    const found = findPerfettoSubtreeExact(child, targetName);
1553→    if (found) return found;
1554→  }
1555→  return null;
1556→}
1557→
1558→/**
1559→ * 提取 marker 名的核心部分用于模糊回退匹配。
1560→ * Gfx.WaitForPresentOnGfxThread → WaitForPresent（去 Gfx. 前缀，去 OnGfxThread 后缀）
1561→ * URP.WaitForPresent → WaitForPresent
1562→ * Core.Update → Update
1563→ */
1564→function extractNameCore(name: string): string {
1565→  // 去前缀（Gfx./URP./Core./Inl_ 等）
1566→  let core = name.replace(/^(Gfx|URP|Core|Inl|PlayerLoop|PostLateUpdate|FinishFrameRendering)\./, '');
1567→  // 去常见后缀（OnGfxThread/OnMainThread 等）
1568→  core = core.replace(/On(GfxThread|MainThread|RenderThread)$/i, '');
1569→  // 取第一个 CamelCase 词组（WaitForPresentOnGfxThread → WaitForPresent）
1570→  const m = core.match(/^([A-Z][a-z]+(?:[A-Z][a-z]+)*)/);
1571→  return m ? m[1] : core;
1572→}
1573→
1574→function collectContainsMatch(node: PerfettoNode, core: string, out: PerfettoNode[]): void {
1575→  if (node.name.includes(core)) out.push(node);
1576→  for (const child of node.children ?? []) collectContainsMatch(child, core, out);
1577→}
1578→
1579→/**
1580→ * 把 perfetto 节点转成 DrillDownNode 兼容结构（renderTreeHTML 只读这些字段）。
1581→ * per-frame avg = totalMs / count（count = 出现帧数）。
1582→ * selfMsPerFrame：perfetto 没直接给 self，置 0（renderTreeHTML 仅在 self>0 且 <total 时显示）。
1583→ * pctOfRoot：用 totalPct/100（相对 UnityMain 总窗口）。
1584→ *
1585→ * WT-033: annotations 是从 findings.json 读的 callTreeAnnotations map（按 nodeName 查）。
1586→ *         转换时若 map 命中则透传 redlineFlag/foldChange/severityTag——render 只呈现不判定。
1587→ *
1588→ * WT-045: 加三重剪枝（maxDepth≤8 + minMsPerFrame≥0.05 + topPerLevel≤8）。
1589→ * perfetto 数据层已剪枝（totalPct≥1.0% + depth≤8），这里双保险，不依赖数据层。
1590→ * 红线条目例外必保留，即使 perFrameMs 低也不剪枝。
1591→ *
1592→ * @param depth 当前递归深度，根节点传 0。depth >= MAX_TREE_DEPTH 不再展开 children。
1593→ */
1594→function perfettoNodeToDrillDown(
1595→  node: PerfettoNode,
1596→  thread: string,
1597→  rootPctOfRoot: number,
1598→  annotations?: Map<string, CallTreeAnnotation>,
1599→  depth: number = 0,
1600→): DrillDownNode {
1601→  const totalMs = node.totalMs ?? 0;
1602→  const count = node.count ?? 1;
1603→  const totalMsPerFrame = count > 0 ? totalMs / count : 0;
1604→  const pctOfRoot = node.totalPct != null ? node.totalPct / 100 : 0;
1605→  // WT-033: 从 findings 注入节点标注（按 nodeName 匹配）
1606→  const ann = annotations?.get(node.name);
1607→
1608→  // WT-045: 三重剪枝 — depth 超过上限不再展开 children
1609→  let children: DrillDownNode[] = [];
1610→  if (depth < MAX_TREE_DEPTH && node.children && node.children.length > 0) {
1611→    const pruned = node.children
1612→      .filter(c => {
1613→        const cTotal = c.totalMs ?? 0;
1614→        const cCount = c.count ?? 1;
1615→        const cMsPerFrame = cCount > 0 ? cTotal / cCount : 0;
1616→        const cAnn = annotations?.get(c.name);
1617→        const hasAnnotation = !!(cAnn?.redlineFlag || cAnn?.foldChange || cAnn?.severityTag);
1618→        return cMsPerFrame >= MIN_MS_PER_FRAME || hasAnnotation;
1619→      })
1620→      .sort((a, b) => {
1621→        const aMs = (a.totalMs ?? 0) / Math.max(1, a.count ?? 1);
1622→        const bMs = (b.totalMs ?? 0) / Math.max(1, b.count ?? 1);
1623→        return bMs - aMs;
1624→      });
1625→
1626→    // 红线条目必保留（即使排在 TOP_PER_LEVEL 之外），非红线取 top N
1627→    const kept: PerfettoNode[] = [];
1628→    let nonRedlineAdded = 0;
1629→    for (const c of pruned) {
1630→      const cAnn = annotations?.get(c.name);
1631→      const hasAnnotation = !!(cAnn?.redlineFlag || cAnn?.foldChange || cAnn?.severityTag);
1632→      if (hasAnnotation) {
1633→        kept.push(c);
1634→      } else if (nonRedlineAdded < TOP_PER_LEVEL) {
1635→        kept.push(c);
1636→        nonRedlineAdded++;
1637→      }
1638→    }
1639→    children = kept.map(c => perfettoNodeToDrillDown(c, thread, rootPctOfRoot, annotations, depth + 1));
1640→  }
1641→
1642→  return {
1643→    name: node.name,
1644→    thread,
1645→    totalMsPerFrame,
1646→    selfMsPerFrame: 0,  // perfetto summary 无 self 字段，置 0（renderTreeHTML 不显示 self 行）
1647→    pctOfRoot,
1648→    presentFrames: count,
1649→    children,
1650→    // WT-033: 透传 findings 的 callTreeAnnotations（只在 map 命中时填，否则 undefined）
1651→    redlineFlag: ann?.redlineFlag ?? undefined,
1652→    foldChange: ann?.foldChange ?? undefined,
1653→    severityTag: ann?.severityTag ?? undefined,
1654→  };
1655→}
1656→
1657→/**
1658→ * perfetto 源的 callTree 重查：读 perfetto-profile-summary.json 的 callTrees，
1659→ * 按 rootMarker 名在树里搜索子树，转成 DrillDownNode。
1660→ * 不走 sqlite / drillDownMarker（那是 unity 工具）。
1661→ *
1662→ * @param dir  run 输出目录（含 narrative.json），形如 .../bk26b-perfetto-triad/2026-07-15_10-36-27
1663→ *             perfetto triad 数据在 dir 的父目录下的 cur/perfetto-profile-summary.json
1664→ */
1665→function requeryPerfettoTrees(
1666→  narrative: NarrativeReport,
1667→  refs: { key: string; rootMarker: string }[],
1668→  dir: string,
1669→): Map<string, DrillDownNode | null> {
1670→  const map = new Map<string, DrillDownNode | null>();
1671→  if (refs.length === 0) return map;
1672→
1673→  // perfetto triad 数据目录：dir 是 .../<runBase>/<timestamp>，triad root = <runBase>
1674→  // perfetto-profile-summary.json 在 <runBase>/cur/ 下（多态报告用 cur 态作主树）
1675→  const triadRoot = path.dirname(dir);  // 去掉时间戳子目录
1676→  const summaryPath = path.join(triadRoot, 'cur', 'perfetto-profile-summary.json');
1677→
1678→  if (!fs.existsSync(summaryPath)) {
1679→    console.warn(`[render-html] perfetto summary not found: ${summaryPath} — all callTrees fallback`);
1680→    for (const ref of refs) map.set(ref.key, null);
1681→    return map;
1682→  }
1683→
1684→  let summary: { callTrees?: { thread?: string; root?: PerfettoNode }[] };
1685→  try {
1686→    summary = JSON.parse(fs.readFileSync(summaryPath, 'utf-8'));
1687→  } catch (e) {
1688→    console.warn(`[render-html] perfetto summary parse failed: ${(e as Error).message} — all callTrees fallback`);
1689→    for (const ref of refs) map.set(ref.key, null);
1690→    return map;
1691→  }
1692→
1693→  const callTrees = Array.isArray(summary.callTrees) ? summary.callTrees : [];
1694→  if (callTrees.length === 0) {
1695→    console.warn('[render-html] perfetto callTrees empty in summary — all callTrees fallback');
1696→    for (const ref of refs) map.set(ref.key, null);
1697→    return map;
1698→  }
1699→
1700→  // 用第一棵树（UnityMain）作主搜索树
1701→  const mainTree = callTrees[0];
1702→  const thread = mainTree.thread ?? 'UnityMain';
1703→  const root = mainTree.root;
1704→  if (!root) {
1705→    console.warn('[render-html] perfetto main tree root missing — all callTrees fallback');
1706→    for (const ref of refs) map.set(ref.key, null);
1707→    return map;
1708→  }
1709→
1710→  // WT-033: 从 findings.json 读 callTreeAnnotations（explore LLM 产的节点标注），建 nodeName → annotation map
1711→  const annotations = loadCallTreeAnnotations(dir);
1712→  if (annotations.size > 0) {
1713→    console.log(`[render-html] loaded ${annotations.size} callTree annotations from findings.json`);
1714→  }
1715→
1716→  for (const ref of refs) {
1717→    const subtree = findPerfettoSubtree(root, ref.rootMarker);
1718→    if (subtree) {
1719→      const tree = perfettoNodeToDrillDown(subtree, thread, 1, annotations);
1720→      map.set(ref.key, tree);
1721→      console.log(`[render-html] perfetto tree OK: "${ref.rootMarker}" → ${tree.totalMsPerFrame.toFixed(2)}ms/frame`);
1722→    } else {
1723→      console.warn(`[render-html] perfetto tree NOT FOUND: "${ref.rootMarker}" — fallback to note`);
1724→      map.set(ref.key, null);
1725→    }
1726→  }
1727→  return map;
1728→}
1729→
1730→async function requeryTrees(
1731→  narrative: NarrativeReport,
1732→  dbPath: string | undefined,
1733→  dir: string,
1734→): Promise<Map<string, DrillDownNode | null>> {
1735→  const map = new Map<string, DrillDownNode | null>();
1736→
1737→  // Collect items with callTree.rootMarker
1738→  type ItemRef = { key: string; rootMarker: string };
1739→  const refs: ItemRef[] = [];
1740→  for (const sec of narrative.sections) {
1741→    sec.items.forEach((item, i) => {
1742→      if (item.callTree?.rootMarker) {
1743→        refs.push({ key: `${sec.heading}::${i}`, rootMarker: item.callTree.rootMarker });
1744→      }
1745→    });
1746→  }
1747→  // WT-046 v4: 不再收集 topConclusions 的 callTree refs——topConclusions 行下不挂 HTML 树，
1748→  // 完整 callTree 只在 §3 下钻出现。topConclusions 行下最多只挂 ASCII 摘要图或 callTree.note。
1749→
1750→  if (refs.length === 0) return map;
1751→
1752→  // perfetto 源：走 perfetto-profile.json，不走 sqlite（DR-45 断链 4 修复）
1753→  if (isPerfettoSource(narrative)) {
1754→    return requeryPerfettoTrees(narrative, refs, dir);
1755→  }
1756→
1757→  // WT-044: unity 多态源（udiff_*）：走 preprocess-result.json 的 aggregatedCallTrees，不走 sqlite
1758→  if (isUnityMultiStateSource(narrative)) {
1759→    return requeryUnityMultiStateTrees(narrative, refs, dir);
1760→  }
1761→
1762→  // unity 单态源：走 sqlite + drillDownMarker
1763→  let db: ReturnType<typeof openPrismDb> | null = null;
1764→  try {
1765→    db = openPrismDb(dbPath);
1766→  } catch (e) {
1767→    console.error('[render-html] Cannot open DB — all callTrees will show note text:', (e as Error).message);
1768→    return map;
1769→  }
1770→
1771→  for (const ref of refs) {
1772→    try {
1773→      const result = drillDownMarker(db, {
1774→        runId: narrative.runId,
1775→        rootMarker: ref.rootMarker,
1776→        maxDepth: 6,
1777→        minMsPerFrame: 0.05,
1778→        topPerLevel: 8,
1779→      });
1780→      const tree = result.data.tree;
1781→      map.set(ref.key, tree);
1782→      console.log(`[render-html] tree OK: "${ref.rootMarker}" → ${result.data.rootTotalMsPerFrame.toFixed(2)}ms/frame`);
1783→    } catch (e) {
1784→      console.warn(`[render-html] tree FAIL: "${ref.rootMarker}" — ${(e as Error).message}`);
1785→      map.set(ref.key, null);
1786→    }
1787→  }
1788→
1789→  try { db.close(); } catch { /* ignore */ }
1790→  return map;
1791→}
