1793→// ─────────────────────── CLI entry ───────────────────────
1794→
1795→function getFlag(name: string): string | undefined {
1796→  const i = process.argv.indexOf(name);
1797→  return i >= 0 && process.argv[i + 1] ? process.argv[i + 1] : undefined;
1798→}
1799→
1800→async function main(): Promise<void> {
1801→  const dir = getFlag('--dir') ?? 'data/prism-out/unity-outside-stressmove';
1802→
1803→  // Require narrative.json — do NOT fall back to findings.json
1804→  const narrativePath = path.join(dir, 'narrative.json');
1805→  if (!fs.existsSync(narrativePath)) {
1806→    console.error(`[render-html] ERROR: narrative.json not found at ${narrativePath}`);
1807→    console.error('[render-html] This renderer requires narrative.json (NarrativeReport shape). Run the narrative stage first.');
1808→    process.exit(1);
1809→  }
1810→
1811→  let narrative: NarrativeReport;
1812→  try {
1813→    narrative = JSON.parse(fs.readFileSync(narrativePath, 'utf-8')) as NarrativeReport;
1814→  } catch (e) {
1815→    console.error(`[render-html] ERROR: failed to parse narrative.json — ${(e as Error).message}`);
1816→    process.exit(1);
1817→  }
1818→
1819→  // DR-44 A2: provenance 强制校验——非 LLM 产出的 narrative.json 拒绝渲染。
1820→  // 脚本拼的 narrative.json（无 narrativeProvenance 或 generatedBy !== 'LLM'）会被拦截，
1821→  // 强制走 narrative LLM 阶段。
1822→  if (
1823→    !narrative.narrativeProvenance ||
1824→    narrative.narrativeProvenance.generatedBy !== 'LLM'
1825→  ) {
1826→    const actual = narrative.narrativeProvenance?.generatedBy ?? 'missing';
1827→    console.error(
1828→      `[render-html] ERROR: narrative.json 的 narrativeProvenance.generatedBy 不是 'LLM'（实际：${actual}）。` +
1829→        `脚本拼的 narrative.json 会被拒绝渲染——必须走 narrative LLM 阶段（DR-44 A2）。`,
1830→    );
1831→    process.exit(1);
1832→  }
1833→
1834→  // Optional verdict.json for numeric metrics
1835→  let verdict: Verdict | null = null;
1836→  const verdictPath = path.join(dir, 'verdict.json');
1837→  if (fs.existsSync(verdictPath)) {
1838→    try {
1839→      verdict = JSON.parse(fs.readFileSync(verdictPath, 'utf-8')) as Verdict;
1840→    } catch {
1841→      console.warn('[render-html] verdict.json found but failed to parse — metric strip will show "—"');
1842→    }
1843→  }
1844→
1845→  const dbPath = getFlag('--db');
1846→  console.log(`[render-html] dir=${dir}  runId=${narrative.runId}  rating=${narrative.rating}`);
1847→  console.log(`[render-html] sections=${narrative.sections.length}  topConclusions=${narrative.topConclusions.length}`);
1848→
1849→  const treesByItemKey = await requeryTrees(narrative, dbPath, dir);
1850→
1851→  const html = renderHTML({ narrative, verdict, treesByItemKey });
1852→
1853→  const outPath = path.join(dir, 'report.html');
1854→  fs.writeFileSync(outPath, html, 'utf-8');
1855→
1856→  const fileSizeKB = (fs.statSync(outPath).size / 1024).toFixed(1);
1857→  console.log(`\n[render-html] Written: ${outPath}`);
1858→  console.log(`[render-html] Size: ${fileSizeKB} KB`);
1859→  console.log(`[render-html] Call-trees re-queried: ${treesByItemKey.size}`);
1860→}
1861→
1862→// ESM: only run main() when this file is the entry point (not when imported by tests)
1863→const __renderHtmlFilename = fileURLToPath(import.meta.url);
1864→const isMainModule = process.argv[1] && path.resolve(process.argv[1]) === __renderHtmlFilename;
1865→if (isMainModule) {
1866→  main().catch(e => {
1867→    console.error('[render-html] Fatal:', e);
1868→    process.exit(1);
1869→  });
1870→}
